"use client";

import { useEffect, useState } from "react";
import Link from "next/link";
import { BarChart3, Bell, CalendarDays, Check, ChevronRight, CircleUserRound, ExternalLink, LayoutDashboard, Menu, MessageCircle, Pause, Play, Plus, Search, Settings, Sparkles, Timer, Users, X } from "lucide-react";
import { cn } from "@/lib/utils/cn";
import { createHerWhatsappUrl } from "@/lib/her/whatsapp";
import { herAdminAppointments, herAdminClients, herAdminServices, herConsultations, herWhatsappLeads } from "@/lib/her/admin/demo-admin-data";
import type { HerAdminAppointment, HerAdminClient, HerAdminService, HerAdminView, HerAppointmentStatus, HerConsultationRequest } from "@/lib/her/admin/admin-types";
import { formatClockDuration, formatCompactDuration, formatLocalTime, getActiveServiceElapsedMs, getCurrentPauseMs, getEstimatedFinishTime, getRemainingServiceMs, getServiceOvertimeMs, getServiceProgress, getServiceVarianceMs, parseAppointmentTimestamp, parseEstimatedDurationMs } from "@/lib/her/admin/service-timer";

const primaryNav = [
  ["overview", "Overview", LayoutDashboard], ["appointments", "Appointments", CalendarDays], ["clients", "Clients", Users], ["services", "Services", Sparkles], ["reports", "Reports", BarChart3],
] as const;

const money = new Intl.NumberFormat("en-JM", { style: "currency", currency: "JMD", maximumFractionDigits: 0 });
const statusStyles: Record<HerAppointmentStatus, string> = { REQUESTED: "bg-amber-100 text-amber-800", CONFIRMED: "bg-emerald-100 text-emerald-800", "CHECKED IN": "bg-sky-100 text-sky-800", "IN SERVICE": "bg-violet-100 text-violet-800", COMPLETED: "bg-[#173d32] text-white", CANCELLED: "bg-rose-100 text-rose-800", "NO-SHOW": "bg-slate-200 text-slate-700" };

export function HerAdminWorkspace() {
  const [view, setView] = useState<HerAdminView>("overview");
  const [menuOpen, setMenuOpen] = useState(false);
  const [appointments, setAppointments] = useState(herAdminAppointments);
  const [consultations, setConsultations] = useState(herConsultations);
  const [services, setServices] = useState(herAdminServices);
  const [selectedAppointment, setSelectedAppointment] = useState<HerAdminAppointment | null>(null);
  const [selectedClient, setSelectedClient] = useState<HerAdminClient | null>(null);
  const [selectedConsultation, setSelectedConsultation] = useState<HerConsultationRequest | null>(null);
  const [editingService, setEditingService] = useState<HerAdminService | null>(null);
  const [creating, setCreating] = useState(false);
  const [rescheduling, setRescheduling] = useState(false);
  const [notice, setNotice] = useState("");
  const [search, setSearch] = useState("");
  const [now, setNow] = useState(() => Date.now());

  const today = appointments.filter((item) => item.dayLabel === "Today");
  const todayBookingValue = today.filter((item) => !["CANCELLED", "NO-SHOW"].includes(item.status)).reduce((sum, item) => sum + item.price, 0);
  const completedValue = appointments.filter((item) => item.status === "COMPLETED").reduce((sum, item) => sum + item.price, 0);
  const activeService = appointments.find((item) => item.status === "IN SERVICE");
  const activeServiceId = activeService?.id;

  useEffect(() => {
    if (!activeServiceId) return;
    const interval = window.setInterval(() => setNow(Date.now()), 1000);
    return () => window.clearInterval(interval);
  }, [activeServiceId]);

  function navigate(next: HerAdminView) { setView(next); setMenuOpen(false); setSearch(""); }
  function updateStatus(id: string, status: HerAppointmentStatus) {
    setAppointments((items) => items.map((item) => item.id === id ? { ...item, status } : item));
    setSelectedAppointment((item) => item?.id === id ? { ...item, status } : item);
    setNotice(`Demo status updated to ${status}.`);
  }
  function startService(id: string) {
    const conflict = appointments.find((item) => item.status === "IN SERVICE" && item.id !== id);
    if (conflict) { setNotice(`ANOTHER SERVICE IS CURRENTLY ACTIVE — ${conflict.client}, ${conflict.service}. Finish or pause that operational session first.`); return; }
    const timestamp = Date.now();
    setNow(timestamp);
    setAppointments((items) => items.map((item) => item.id === id ? { ...item, status: "IN SERVICE", serviceStartedAt: timestamp, serviceCompletedAt: undefined, pausedAt: undefined, accumulatedPausedMs: 0 } : item));
    setSelectedAppointment((item) => item?.id === id ? { ...item, status: "IN SERVICE", serviceStartedAt: timestamp, serviceCompletedAt: undefined, pausedAt: undefined, accumulatedPausedMs: 0 } : item);
    setNotice("SERVICE STARTED — live timing is active in this demo session.");
  }
  function pauseService(id: string) {
    const timestamp = Date.now(); setNow(timestamp);
    setAppointments((items) => items.map((item) => item.id === id && !item.pausedAt ? { ...item, pausedAt: timestamp } : item));
    setSelectedAppointment((item) => item?.id === id && !item.pausedAt ? { ...item, pausedAt: timestamp } : item);
    setNotice("SERVICE PAUSED — active elapsed time is held.");
  }
  function resumeService(id: string) {
    const timestamp = Date.now(); setNow(timestamp);
    const resume = (item: HerAdminAppointment) => item.pausedAt ? { ...item, pausedAt: undefined, accumulatedPausedMs: (item.accumulatedPausedMs ?? 0) + timestamp - item.pausedAt } : item;
    setAppointments((items) => items.map((item) => item.id === id ? resume(item) : item));
    setSelectedAppointment((item) => item?.id === id ? resume(item) : item);
    setNotice("SERVICE RESUMED — live timing continues from timestamps.");
  }
  function completeService(id: string) {
    const timestamp = Date.now(); setNow(timestamp);
    const complete = (item: HerAdminAppointment) => ({ ...item, status: "COMPLETED" as const, serviceCompletedAt: timestamp, accumulatedPausedMs: (item.accumulatedPausedMs ?? 0) + (item.pausedAt ? timestamp - item.pausedAt : 0), pausedAt: undefined });
    setAppointments((items) => items.map((item) => item.id === id ? complete(item) : item));
    setSelectedAppointment((item) => item?.id === id ? complete(item) : item);
    setNotice("SERVICE COMPLETED — duration summary is now available. Payment status was not changed.");
  }

  return <div className="min-h-screen bg-[#f6f1e8] text-[#173d32]">
    <aside className={cn("fixed inset-y-0 left-0 z-50 w-[278px] border-r border-[#173d32]/10 bg-[#163d32] p-5 text-white transition-transform lg:translate-x-0", menuOpen ? "translate-x-0" : "-translate-x-full")} aria-label="HER Admin navigation">
      <div className="flex items-start justify-between"><div><p className="font-serif text-3xl">HER</p><p className="mt-1 text-[10px] font-black uppercase tracking-[.18em] text-[#dfc48d]">Salon &amp; Wellness</p><p className="mt-3 text-xs font-black uppercase tracking-[.22em] text-white/45">Admin</p></div><button type="button" onClick={() => setMenuOpen(false)} aria-label="Close navigation" className="grid h-11 w-11 place-items-center rounded-xl border border-white/10 lg:hidden"><X className="h-5 w-5"/></button></div>
      <nav className="mt-10 space-y-1">{primaryNav.map(([id,label,Icon]) => <button key={id} type="button" onClick={() => navigate(id)} className={cn("flex min-h-12 w-full items-center gap-3 rounded-xl px-4 text-left text-sm font-bold", view === id ? "bg-[#dfc48d] text-[#173d32]" : "text-white/65 hover:bg-white/8 hover:text-white")}><Icon className="h-4.5 w-4.5"/>{label}</button>)}</nav>
      <div className="mt-6 border-t border-white/10 pt-6"><button type="button" onClick={() => navigate("consultations")} className={cn("flex min-h-12 w-full items-center justify-between rounded-xl px-4 text-sm font-bold", view === "consultations" ? "bg-white/12 text-white" : "text-white/60")}><span className="flex items-center gap-3"><MessageCircle className="h-4.5 w-4.5"/>Consultations</span><span className="rounded-full bg-[#d7b7aa] px-2 py-0.5 text-[10px] text-[#173d32]">{consultations.filter((item) => item.status === "NEW").length}</span></button></div>
      <div className="absolute inset-x-5 bottom-5 space-y-1"><Link href="/her" className="flex min-h-11 items-center gap-3 rounded-xl px-4 text-sm font-bold text-white/60 hover:bg-white/8"><ExternalLink className="h-4 w-4"/>HER Website</Link><button type="button" onClick={() => navigate("settings")} className="flex min-h-11 w-full items-center gap-3 rounded-xl px-4 text-sm font-bold text-white/60 hover:bg-white/8"><Settings className="h-4 w-4"/>Settings</button><div className="mt-3 rounded-xl border border-[#dfc48d]/20 bg-[#dfc48d]/8 px-4 py-3 text-[10px] font-black uppercase tracking-[.14em] text-[#dfc48d]">Interactive Admin Preview</div></div>
    </aside>

    <div className="lg:pl-[278px]">
      <header className="sticky top-0 z-30 border-b border-[#173d32]/10 bg-[#f6f1e8]/95 px-4 py-3 backdrop-blur-xl sm:px-6 lg:px-8"><div className="mx-auto flex max-w-[1450px] flex-wrap items-center gap-3"><button type="button" onClick={() => setMenuOpen(true)} aria-label="Open admin navigation" className="grid h-11 w-11 place-items-center rounded-xl border border-[#173d32]/12 bg-white lg:hidden"><Menu className="h-5 w-5"/></button><div className="relative order-last w-full sm:order-none sm:max-w-xl sm:flex-1"><Search className="absolute left-4 top-1/2 h-4 w-4 -translate-y-1/2 text-[#6c7b73]"/><input value={search} onChange={(event) => setSearch(event.target.value)} aria-label="Search HER Admin" placeholder="Search clients, appointments or services..." className="min-h-11 w-full rounded-xl border border-[#173d32]/10 bg-white pl-11 pr-4 text-sm outline-none focus:border-[#b28a4d]"/></div><div className="ml-auto flex items-center gap-2"><button type="button" onClick={() => navigate("consultations")} aria-label="View notifications" className="relative grid h-11 w-11 place-items-center rounded-xl border border-[#173d32]/10 bg-white"><Bell className="h-4.5 w-4.5"/><span className="absolute right-2 top-2 h-2 w-2 rounded-full bg-[#b07a6d]"/></button><button type="button" onClick={() => setCreating(true)} className="inline-flex min-h-11 items-center gap-2 rounded-xl bg-[#173d32] px-4 text-xs font-black uppercase tracking-[.08em] text-white"><Plus className="h-4 w-4"/><span className="hidden sm:inline">New appointment</span></button></div></div></header>

      <main className="mx-auto max-w-[1450px] p-4 pb-20 sm:p-6 lg:p-8">
        {notice ? <div role="status" className="mb-5 flex items-center justify-between rounded-xl border border-emerald-200 bg-emerald-50 px-4 py-3 text-sm font-bold text-emerald-800"><span>{notice}</span><button type="button" aria-label="Dismiss notification" onClick={() => setNotice("")}><X className="h-4 w-4"/></button></div> : null}
        {view === "overview" ? <Overview appointments={appointments} consultations={consultations} todayBookingValue={todayBookingValue} now={now} onOpen={setSelectedAppointment} onNavigate={navigate} /> : null}
        {view === "appointments" ? <Appointments appointments={appointments} search={search} now={now} onOpen={setSelectedAppointment} /> : null}
        {view === "clients" ? <Clients clients={herAdminClients} search={search} onOpen={setSelectedClient} /> : null}
        {view === "consultations" ? <Consultations items={consultations} onOpen={setSelectedConsultation} /> : null}
        {view === "services" ? <Services services={services} search={search} onEdit={setEditingService} /> : null}
        {view === "reports" ? <Reports appointments={appointments} completedValue={completedValue} /> : null}
        {view === "settings" ? <SettingsView /> : null}
      </main>
    </div>
    {menuOpen ? <button type="button" aria-label="Close navigation overlay" onClick={() => setMenuOpen(false)} className="fixed inset-0 z-40 bg-black/35 lg:hidden"/> : null}
    {selectedAppointment ? <AppointmentDialog appointment={selectedAppointment} now={now} onClose={() => { setSelectedAppointment(null); setRescheduling(false); }} onStatus={updateStatus} onStart={startService} onPause={pauseService} onResume={resumeService} onComplete={completeService} rescheduling={rescheduling} setRescheduling={setRescheduling} onReschedule={(date,time) => { setAppointments((items) => items.map((item) => item.id === selectedAppointment.id ? {...item,date,time,dayLabel:"Rescheduled"} : item)); setSelectedAppointment({...selectedAppointment,date,time,dayLabel:"Rescheduled"}); setRescheduling(false); setNotice("Demo appointment rescheduled."); }} /> : null}
    {selectedClient ? <ClientDialog client={selectedClient} appointments={appointments.filter((item) => item.clientId === selectedClient.id)} onClose={() => setSelectedClient(null)} /> : null}
    {selectedConsultation ? <ConsultationDialog item={selectedConsultation} onClose={() => setSelectedConsultation(null)} onReviewed={() => { setConsultations((items) => items.map((item) => item.id === selectedConsultation.id ? {...item,status:"REVIEWED"} : item)); setSelectedConsultation({...selectedConsultation,status:"REVIEWED"}); setNotice("Consultation marked reviewed in demo state."); }} onConvert={() => { setSelectedConsultation(null); setCreating(true); }} /> : null}
    {editingService ? <ServiceDialog service={editingService} onClose={() => setEditingService(null)} onSave={(updated) => { setServices((items) => items.map((item) => item.id === updated.id ? updated : item)); setEditingService(null); setNotice("Demo service change applied in memory — not saved to production."); }} /> : null}
    {creating ? <NewAppointmentDialog clients={herAdminClients} services={services} onClose={() => setCreating(false)} onCreate={(appointment) => { setAppointments((items) => [appointment, ...items]); setCreating(false); setNotice("DEMO APPOINTMENT CREATED — not saved to production."); }} /> : null}
  </div>;
}

function PageTitle({ eyebrow, title, copy, action }: { eyebrow: string; title: string; copy: string; action?: React.ReactNode }) { return <div className="mb-7 flex flex-col justify-between gap-5 md:flex-row md:items-end"><div><p className="text-[10px] font-black uppercase tracking-[.2em] text-[#a1783f]">{eyebrow}</p><h1 className="mt-2 font-serif text-3xl tracking-[-.03em] sm:text-4xl">{title}</h1><p className="mt-2 text-sm text-[#697970]">{copy}</p></div>{action}</div>; }
function Card({ children, className }: { children: React.ReactNode; className?: string }) { return <section className={cn("rounded-2xl border border-[#173d32]/10 bg-white p-5 shadow-[0_12px_40px_rgba(23,61,50,.045)] sm:p-6", className)}>{children}</section>; }
function StatusBadge({ status }: { status: HerAppointmentStatus }) { return <span className={cn("inline-flex rounded-full px-2.5 py-1 text-[9px] font-black tracking-[.08em]", statusStyles[status])}>{status}</span>; }

function Overview({ appointments, consultations, todayBookingValue, now, onOpen, onNavigate }: { appointments: HerAdminAppointment[]; consultations: HerConsultationRequest[]; todayBookingValue: number; now:number; onOpen: (item:HerAdminAppointment)=>void; onNavigate:(view:HerAdminView)=>void }) {
  const today = appointments.filter((item) => item.dayLabel === "Today");
  return <><PageTitle eyebrow="Tuesday, September 30" title="Good afternoon, Andrea." copy="HER is open today · 8:00 AM–8:00 PM" action={<span className="w-fit rounded-full border border-emerald-200 bg-emerald-50 px-4 py-2 text-xs font-black text-emerald-800">● Open today</span>}/>
    <div className="grid grid-cols-2 gap-3 xl:grid-cols-4">{[["Today's appointments",today.length],["Consultations",consultations.filter((item)=>item.status==="NEW").length],["Available windows",2],["Today's booking value",money.format(todayBookingValue)]].map(([label,value],index)=><Card key={label as string}><p className="text-2xl font-black sm:text-3xl">{value}</p><p className="mt-2 text-xs font-black uppercase tracking-[.08em] text-[#64756c]">{label}</p><p className="mt-1 text-[10px] text-[#89958f]">{index===3?"Demo · scheduled value":"Demo operations"}</p></Card>)}</div>
    <NowServing appointments={appointments} now={now} onOpen={onOpen}/>
    <div className="mt-5 grid gap-5 xl:grid-cols-[1.35fr_.65fr]"><Card><div className="flex items-center justify-between"><div><p className="text-[10px] font-black uppercase tracking-[.18em] text-[#a1783f]">Today&apos;s journey</p><h2 className="mt-2 font-serif text-2xl">Who is coming today?</h2></div><CalendarDays className="h-5 w-5 text-[#a1783f]"/></div><div className="mt-6 space-y-2">{today.map((item)=><button type="button" key={item.id} onClick={()=>onOpen(item)} className="grid min-h-20 w-full grid-cols-[64px_1fr_auto] items-center gap-3 rounded-xl border border-[#173d32]/8 px-3 text-left transition hover:border-[#b28a4d]/45 sm:grid-cols-[80px_1fr_auto]"><span className="text-xs font-black">{item.time}</span><span className="min-w-0"><span className="block truncate font-bold">{item.client}</span><span className="block truncate text-xs text-[#6d7d74]">{item.service} · {money.format(item.price)}</span>{item.status==="IN SERVICE"?<span className="mt-1 block text-[10px] font-black text-[#8a6633]">{getServiceOvertimeMs(item,now) ? `${formatCompactDuration(getServiceOvertimeMs(item,now)??0)} over estimate` : `${formatCompactDuration(getRemainingServiceMs(item,now)??0)} remaining`}{item.pausedAt?" · PAUSED":""}</span>:null}</span><span className="flex items-center gap-2"><StatusBadge status={item.status}/><ChevronRight className="hidden h-4 w-4 sm:block"/></span></button>)}</div></Card>
      <div className="space-y-5"><Card><p className="text-[10px] font-black uppercase tracking-[.18em] text-[#a1783f]">Needs attention</p><div className="mt-4 space-y-3 text-sm">{[`${consultations.filter((item)=>item.status==="NEW").length} consultation requests`,`1 appointment awaiting confirmation`,`3 WhatsApp inquiries`,`1 client requested rescheduling`].map((item)=><div key={item} className="flex items-center justify-between gap-3"><span>{item}</span><button type="button" onClick={()=>onNavigate("consultations")} className="text-[10px] font-black uppercase text-[#9a7139]">Review</button></div>)}</div></Card><Card><p className="text-[10px] font-black uppercase tracking-[.18em] text-[#a1783f]">Next available</p><div className="mt-4 space-y-3">{[["Today","4:30 PM"],["Today","7:00 PM"],["Tomorrow","8:00 AM"]].map(([day,time])=><div key={day+time} className="flex justify-between text-sm"><span className="text-[#6d7d74]">{day}</span><strong>{time}</strong></div>)}</div><p className="mt-4 text-[10px] font-bold uppercase tracking-[.08em] text-[#9a7139]">Demo availability only</p></Card></div>
    </div><div className="mt-5 grid gap-5 md:grid-cols-2"><Card><div className="flex items-center justify-between"><div><p className="text-[10px] font-black uppercase tracking-[.18em] text-[#a1783f]">WhatsApp inquiries</p><h2 className="mt-2 font-serif text-2xl">3 today</h2></div><MessageCircle className="h-5 w-5"/></div><div className="mt-4 space-y-2">{herWhatsappLeads.map((lead)=><p key={lead} className="rounded-xl bg-[#f7f2e9] p-3 text-sm">{lead} <span className="text-[9px] font-black text-[#9a7139]">DEMO</span></p>)}</div><Link target="_blank" rel="noreferrer" href={createHerWhatsappUrl()} className="mt-4 inline-flex min-h-11 items-center gap-2 text-sm font-black"><ExternalLink className="h-4 w-4"/>Open WhatsApp</Link></Card><Card className="bg-[#173d32] text-white"><p className="text-[10px] font-black uppercase tracking-[.18em] text-[#dfc48d]">Front desk focus</p><h2 className="mt-3 font-serif text-3xl">Next: Sarah at 9:00 AM</h2><p className="mt-3 text-sm text-white/60">HER RESET · Confirmed · WhatsApp preferred</p><button type="button" onClick={()=>onOpen(today[0])} className="mt-6 min-h-11 rounded-xl bg-[#dfc48d] px-5 text-sm font-black text-[#173d32]">Open appointment</button></Card></div>
  </>;
}

function NowServing({appointments,now,onOpen}:{appointments:HerAdminAppointment[];now:number;onOpen:(item:HerAdminAppointment)=>void}) {
  const active=appointments.find((item)=>item.status==="IN SERVICE");
  if(!active){const next=appointments.find((item)=>item.dayLabel==="Today"&&["REQUESTED","CONFIRMED","CHECKED IN"].includes(item.status));return <Card className="mt-5 border-[#b28a4d]/25 bg-[#173d32] text-white"><div className="flex items-center gap-3"><Timer className="h-5 w-5 text-[#dfc48d]"/><p className="text-[10px] font-black uppercase tracking-[.18em] text-[#dfc48d]">Now serving</p></div><h2 className="mt-4 font-serif text-2xl">No service currently in progress</h2>{next?<button type="button" onClick={()=>onOpen(next)} className="mt-5 flex w-full items-center justify-between rounded-xl bg-white/8 p-4 text-left"><span><span className="block text-[10px] font-black uppercase tracking-[.12em] text-white/45">Next appointment</span><span className="mt-1 block font-bold">{next.time} — {next.client}</span></span><ChevronRight className="h-4 w-4"/></button>:null}</Card>}
  const remaining=getRemainingServiceMs(active,now); const overtime=getServiceOvertimeMs(active,now); const finish=getEstimatedFinishTime(active);
  const currentSchedule=parseAppointmentTimestamp(active.date,active.time); const upcoming=appointments.filter((item)=>item.id!==active.id&&item.date===active.date&&!['CANCELLED','NO-SHOW','COMPLETED'].includes(item.status)).map((item)=>({item,time:parseAppointmentTimestamp(item.date,item.time)})).filter((entry):entry is {item:HerAdminAppointment;time:number}=>entry.time!==null&&entry.time>(currentSchedule??0)).sort((a,b)=>a.time-b.time)[0];
  const turnaround=upcoming&&finish!==null?upcoming.time-finish:null; const nextIn=upcoming?upcoming.time-now:null;
  const scheduleLabel=turnaround===null?null:turnaround>0?`${formatCompactDuration(turnaround)} TURNAROUND`:turnaround===0?"BACK-TO-BACK":`POTENTIAL SCHEDULE OVERLAP · ${formatCompactDuration(Math.abs(turnaround))}`;
  return <Card className="mt-5 border-[#b28a4d]/30 bg-[#173d32] text-white"><div className="grid gap-6 lg:grid-cols-[1fr_auto] lg:items-center"><div><div className="flex items-center gap-3"><Timer className="h-5 w-5 text-[#dfc48d]"/><p className="text-[10px] font-black uppercase tracking-[.18em] text-[#dfc48d]">Now serving · {active.pausedAt?"Service paused":overtime?"Over estimated time":"Service in progress"}</p></div><h2 className="mt-4 font-serif text-3xl">{active.client}</h2><p className="mt-1 font-bold text-white/65">{active.service}</p><p className="mt-5 text-2xl font-black text-[#dfc48d]">{overtime?`${formatCompactDuration(overtime)} over estimate`:remaining===null?"Estimated duration not set":`${formatCompactDuration(remaining)} remaining`}</p><p className="mt-2 text-xs text-white/50">Expected finish {formatLocalTime(finish??undefined)}</p></div><button type="button" onClick={()=>onOpen(active)} className="min-h-12 rounded-xl bg-[#dfc48d] px-5 text-sm font-black text-[#173d32]">Open appointment</button></div>{upcoming?<div className="mt-6 grid gap-3 border-t border-white/10 pt-5 sm:grid-cols-2"><div><p className="text-[10px] font-black uppercase tracking-[.12em] text-white/40">Next appointment</p><p className="mt-1 font-bold">{upcoming.item.time} · {upcoming.item.client}</p></div><div><p className="text-[10px] font-black uppercase tracking-[.12em] text-white/40">Schedule context</p><p className="mt-1 font-bold text-[#dfc48d]">{overtime&&nextIn!==null&&nextIn>0?`Next appointment in ${formatCompactDuration(nextIn)}`:scheduleLabel}</p></div></div>:<p className="mt-5 border-t border-white/10 pt-5 text-sm text-white/50">No later appointment is scheduled today.</p>}</Card>;
}

function Appointments({ appointments, search, now, onOpen }: { appointments:HerAdminAppointment[]; search:string; now:number; onOpen:(item:HerAdminAppointment)=>void }) {
  const [filter,setFilter]=useState("TODAY"); const query=search.toLowerCase(); const filtered=appointments.filter((item)=>(filter==="TODAY"?item.dayLabel==="Today":filter==="UPCOMING"?item.dayLabel!=="Today":item.status===filter)&&`${item.client} ${item.service}`.toLowerCase().includes(query));
  return <><PageTitle eyebrow="Front desk" title="Appointments" copy="Manage the demo journey from request through completed service."/><div className="mb-5 flex flex-wrap gap-2">{["TODAY","UPCOMING","REQUESTED","COMPLETED","CANCELLED"].map((item)=><button type="button" key={item} onClick={()=>setFilter(item)} className={cn("min-h-10 rounded-full px-4 text-xs font-black",filter===item?"bg-[#173d32] text-white":"border border-[#173d32]/10 bg-white")}>{item}</button>)}</div><div className="space-y-3">{filtered.map((item)=><button key={item.id} type="button" onClick={()=>onOpen(item)} className="grid w-full gap-3 rounded-2xl border border-[#173d32]/10 bg-white p-5 text-left sm:grid-cols-[90px_1fr_1fr_auto] sm:items-center"><div><p className="text-sm font-black">{item.time}</p><p className="text-xs text-[#77857e]">{item.dayLabel}</p></div><div><p className="font-black">{item.client}</p><p className="mt-1 text-xs text-[#77857e]">{item.contactPreference}</p></div><div><p className="text-sm font-bold">{item.service}</p><p className="mt-1 text-xs text-[#77857e]">{item.duration} · {money.format(item.price)}</p>{item.status==="IN SERVICE"?<p className="mt-1 text-[10px] font-black text-[#9a7139]">{item.pausedAt?"SERVICE PAUSED":getServiceOvertimeMs(item,now)?`${formatCompactDuration(getServiceOvertimeMs(item,now)??0)} OVERTIME`:`${formatCompactDuration(getRemainingServiceMs(item,now)??0)} REMAINING`}</p>:null}</div><div className="flex items-center justify-between gap-3"><StatusBadge status={item.status}/><ChevronRight className="h-4 w-4"/></div></button>)}{filtered.length===0?<p className="rounded-2xl border border-dashed border-[#173d32]/20 p-10 text-center text-sm text-[#738179]">No demo appointments match this view.</p>:null}</div></>;
}

function Clients({clients,search,onOpen}:{clients:HerAdminClient[];search:string;onOpen:(item:HerAdminClient)=>void}) { const query=search.toLowerCase(); const filtered=clients.filter((item)=>`${item.name} ${item.phone} ${item.email}`.toLowerCase().includes(query)); return <><PageTitle eyebrow="Salon directory" title="Clients" copy="Contact details, service preferences, and salon appointment history only."/><div className="grid gap-3 lg:grid-cols-2">{filtered.map((item)=><button type="button" key={item.id} onClick={()=>onOpen(item)} className="rounded-2xl border border-[#173d32]/10 bg-white p-5 text-left"><div className="flex items-start justify-between"><span className="grid h-11 w-11 place-items-center rounded-full bg-[#f1e5d2]"><CircleUserRound className="h-5 w-5"/></span><span className="text-xs font-black text-[#9a7139]">{item.visits} VISITS</span></div><h2 className="mt-5 text-lg font-black">{item.name}</h2><p className="mt-1 text-sm text-[#6d7d74]">{item.phone} · {item.email}</p><div className="mt-5 grid grid-cols-2 gap-3 text-xs"><div><p className="text-[#87928c]">Last visit</p><p className="mt-1 font-bold">{item.lastVisit}</p></div><div><p className="text-[#87928c]">Next</p><p className="mt-1 font-bold">{item.nextAppointment}</p></div></div><p className="mt-4 text-sm"><span className="text-[#87928c]">Preferred:</span> <strong>{item.preferredService}</strong></p></button>)}</div></>; }

function Consultations({items,onOpen}:{items:HerConsultationRequest[];onOpen:(item:HerConsultationRequest)=>void}) { return <><PageTitle eyebrow="Consultation inbox" title="Consultations" copy="General customer-selected concerns for professional review — not diagnoses."/><div className="space-y-3">{items.map((item)=><button type="button" key={item.id} onClick={()=>onOpen(item)} className="grid w-full gap-4 rounded-2xl border border-[#173d32]/10 bg-white p-5 text-left sm:grid-cols-[1fr_1fr_auto] sm:items-center"><div><p className="font-black">{item.client}</p><p className="mt-1 text-sm text-[#6d7d74]">{item.concern}</p></div><div><p className="text-xs text-[#87928c]">Requested</p><p className="mt-1 text-sm font-bold">{item.requested} · {item.contactPreference}</p></div><span className={cn("w-fit rounded-full px-3 py-1 text-[10px] font-black",item.status==="NEW"?"bg-[#d7b7aa]/45 text-[#6d4036]":"bg-[#f1e5d2] text-[#73582f]")}>{item.status}</span></button>)}</div></>; }

function Services({services,search,onEdit}:{services:HerAdminService[];search:string;onEdit:(item:HerAdminService)=>void}) { const query=search.toLowerCase(); const filtered=services.filter((item)=>`${item.name} ${item.category}`.toLowerCase().includes(query)); return <><PageTitle eyebrow="Approved catalogue" title="Services" copy="Demo-manage visibility and booking rules. Changes remain in memory only."/><div className="grid gap-3 md:grid-cols-2 xl:grid-cols-3">{filtered.map((item)=><button type="button" key={item.id} onClick={()=>onEdit(item)} className={cn("flex min-h-44 flex-col rounded-2xl border p-5 text-left",item.featured?"border-[#b28a4d]/40 bg-[#173d32] text-white":"border-[#173d32]/10 bg-white")}><div className="flex items-start justify-between gap-3"><span className={cn("text-[9px] font-black uppercase tracking-[.12em]",item.featured?"text-[#dfc48d]":"text-[#9a7139]")}>{item.category}</span><span className={cn("rounded-full px-2 py-1 text-[9px] font-black",item.status==="ACTIVE"?"bg-emerald-100 text-emerald-800":"bg-slate-200 text-slate-700")}>{item.status}</span></div><h2 className="mt-auto font-bold">{item.name}</h2><div className="mt-3 flex items-end justify-between"><span className={item.featured?"font-black text-[#dfc48d]":"font-black text-[#8b6633]"}>{item.price}</span><span className={cn("text-xs",item.featured?"text-white/55":"text-[#79867f]")}>{item.duration}</span></div></button>)}</div></>; }

function Reports({appointments,completedValue}:{appointments:HerAdminAppointment[];completedValue:number}) { const counts=[6,3,1,5,4,2]; const labels=["HER Reset","Silk Press","Scalp Therapy","Coil Hydration","HER Time","Wellness"]; const booking=appointments.filter((item)=>!["CANCELLED","NO-SHOW"].includes(item.status)).reduce((sum,item)=>sum+item.price,0); const timedCompleted=appointments.filter((item)=>item.status==="COMPLETED"&&item.serviceStartedAt&&item.serviceCompletedAt); return <><PageTitle eyebrow="Demo analytics" title="Reports" copy="A light business overview — not a financial accounting system."/><div className="grid grid-cols-2 gap-3 lg:grid-cols-5">{[["Appointments",appointments.length],["Consultations",herConsultations.length],["Completed services",appointments.filter((i)=>i.status==="COMPLETED").length],["Booking value",money.format(booking)],["Average booking value",money.format(Math.round(booking/appointments.length))]].map(([label,value])=><Card key={label as string}><p className="text-xl font-black">{value}</p><p className="mt-2 text-[10px] font-black uppercase tracking-[.08em] text-[#728078]">{label}</p></Card>)}</div><div className="mt-5 grid gap-5 lg:grid-cols-2"><Card><p className="text-[10px] font-black uppercase tracking-[.18em] text-[#a1783f]">Service mix</p><div className="mt-6 space-y-4">{labels.map((label,index)=><div key={label}><div className="flex justify-between text-xs"><strong>{label}</strong><span>{counts[index]}</span></div><div className="mt-2 h-2 rounded-full bg-[#eee5d6]"><div className="h-full rounded-full bg-[#173d32]" style={{width:`${counts[index]/6*100}%`}}/></div></div>)}</div></Card><Card><p className="text-[10px] font-black uppercase tracking-[.18em] text-[#a1783f]">Value clarity</p><h2 className="mt-4 font-serif text-3xl">{money.format(booking)}</h2><p className="mt-1 text-sm font-bold">Booking value</p><h2 className="mt-7 font-serif text-3xl">{money.format(completedValue)}</h2><p className="mt-1 text-sm font-bold">Completed service value</p><p className="mt-6 text-xs leading-6 text-[#748179]">No payment collection is connected. Scheduled value is not represented as revenue.</p></Card><Card className="lg:col-span-2"><p className="text-[10px] font-black uppercase tracking-[.18em] text-[#a1783f]">Service duration</p>{timedCompleted.length?<div className="mt-5 grid gap-3 sm:grid-cols-2">{timedCompleted.map((item)=><div key={item.id} className="rounded-xl bg-[#f7f2e9] p-4"><p className="font-black">{item.service}</p><p className="mt-2 text-sm text-[#66766d]">Estimated: {item.duration}</p><p className="mt-1 text-sm text-[#66766d]">Actual: {formatCompactDuration(getActiveServiceElapsedMs(item,item.serviceCompletedAt))}</p></div>)}</div>:<p className="mt-5 text-sm font-bold text-[#748179]">NOT ENOUGH COMPLETED SERVICES YET</p>}<p className="mt-4 text-xs text-[#7b8881]">Duration information is operational only and is not employee-performance scoring.</p></Card></div></>; }

function SettingsView(){return <><PageTitle eyebrow="Demo configuration" title="Settings" copy="Read-only operating profile for this interactive preview."/><Card className="max-w-3xl"><dl className="divide-y divide-[#173d32]/8">{[["Business","HER Salon & Wellness at Happy-Park"],["Location","Southfield, St. Elizabeth"],["Hours","Sunday–Sunday · 8:00 AM–8:00 PM"],["WhatsApp","876-218-9834"],["Website","happy-park.com/her"],["Email","jawihairspa@gmail.com"],["Online Booking","Enabled — Demo"],["Online Consultations","Enabled — Demo"]].map(([term,value])=><div key={term} className="grid gap-1 py-4 sm:grid-cols-[180px_1fr]"><dt className="text-xs font-black uppercase tracking-[.08em] text-[#7a8780]">{term}</dt><dd className="font-bold">{value}</dd></div>)}</dl><p className="mt-5 rounded-xl bg-[#f6eee0] p-4 text-xs font-bold text-[#76572c]">Demo settings are not saved to production.</p></Card></>;}

function DialogShell({title,onClose,children}:{title:string;onClose:()=>void;children:React.ReactNode}) { return <div className="fixed inset-0 z-[100] flex items-end justify-center bg-[#081812]/55 p-0 backdrop-blur-sm sm:items-center sm:p-5" role="dialog" aria-modal="true" aria-label={title}><div className="max-h-[94vh] w-full max-w-2xl overflow-y-auto rounded-t-[2rem] bg-[#fffaf0] p-5 shadow-2xl sm:rounded-[2rem] sm:p-7"><div className="flex items-center justify-between"><h2 className="font-serif text-2xl">{title}</h2><button type="button" onClick={onClose} aria-label="Close dialog" className="grid h-11 w-11 place-items-center rounded-xl border border-[#173d32]/10 bg-white"><X className="h-5 w-5"/></button></div>{children}</div></div>; }

function AppointmentDialog({appointment,now,onClose,onStatus,onStart,onPause,onResume,onComplete,rescheduling,setRescheduling,onReschedule}:{appointment:HerAdminAppointment;now:number;onClose:()=>void;onStatus:(id:string,status:HerAppointmentStatus)=>void;onStart:(id:string)=>void;onPause:(id:string)=>void;onResume:(id:string)=>void;onComplete:(id:string)=>void;rescheduling:boolean;setRescheduling:(value:boolean)=>void;onReschedule:(date:string,time:string)=>void}) { const service=herAdminServices.find((item)=>item.id===appointment.serviceId); const [date,setDate]=useState(appointment.date); const [time,setTime]=useState(appointment.time); const [confirmingComplete,setConfirmingComplete]=useState(false); return <DialogShell title={appointment.client} onClose={onClose}>
  {appointment.status==="IN SERVICE"?<ServiceTimerPanel appointment={appointment} now={now} onPause={()=>onPause(appointment.id)} onResume={()=>onResume(appointment.id)} onComplete={()=>setConfirmingComplete(true)}/>:appointment.status==="COMPLETED"&&appointment.serviceCompletedAt?<CompletionSummary appointment={appointment}/>:<div className="mt-6 rounded-2xl bg-white p-5"><div className="flex items-start justify-between gap-4"><div><p className="text-sm font-black">{appointment.dayLabel} · {appointment.time}</p><h3 className="mt-2 text-xl font-black">{appointment.service}</h3><p className="mt-1 text-sm text-[#718078]">Estimated duration: {parseEstimatedDurationMs(appointment.duration)===null?"NOT SET":appointment.duration} · {money.format(appointment.price)}</p></div><StatusBadge status={appointment.status}/></div>{service?.includes?<ul className="mt-5 grid gap-2 text-sm text-[#607067] sm:grid-cols-2">{service.includes.map((item)=><li key={item} className="flex gap-2"><Check className="mt-0.5 h-4 w-4 text-[#9a7139]"/>{item}</li>)}</ul>:null}</div>}
  {confirmingComplete?<div className="mt-5 rounded-2xl border border-[#b28a4d]/35 bg-[#f5ead8] p-5" role="alertdialog" aria-label="Complete this service?"><p className="text-[10px] font-black uppercase tracking-[.16em] text-[#8a6633]">Complete this service?</p><h3 className="mt-2 text-lg font-black">{appointment.service} · {appointment.client}</h3><p className="mt-2 text-sm text-[#6d6558]">This will mark the demo appointment completed and stop its operational timer.</p><div className="mt-5 grid grid-cols-2 gap-3"><button type="button" onClick={()=>setConfirmingComplete(false)} className="min-h-12 rounded-xl border border-[#173d32]/12 bg-white font-black">Cancel</button><button type="button" onClick={()=>{setConfirmingComplete(false);onComplete(appointment.id)}} className="min-h-12 rounded-xl bg-[#173d32] font-black text-white">Complete service</button></div></div>:null}
  {rescheduling?<div className="mt-5 grid gap-4 rounded-2xl border border-[#b28a4d]/30 p-5 sm:grid-cols-2"><label className="text-sm font-bold">New date<input type="date" value={date} onChange={(e)=>setDate(e.target.value)} className="mt-2 min-h-12 w-full rounded-xl border px-3"/></label><label className="text-sm font-bold">New time<input value={time} onChange={(e)=>setTime(e.target.value)} className="mt-2 min-h-12 w-full rounded-xl border px-3"/></label><button type="button" onClick={()=>onReschedule(date,time)} className="min-h-11 rounded-xl bg-[#173d32] px-4 text-sm font-black text-white sm:col-span-2">Confirm demo reschedule</button></div>:null}
  <div className="mt-6 flex flex-wrap gap-2">{appointment.status==="CONFIRMED"?<button type="button" onClick={()=>onStatus(appointment.id,"CHECKED IN")} className="min-h-12 rounded-xl bg-[#173d32] px-5 text-sm font-black text-white">Check in</button>:null}{appointment.status==="CHECKED IN"?<button type="button" onClick={()=>onStart(appointment.id)} className="min-h-12 rounded-xl bg-[#173d32] px-5 text-sm font-black text-white"><Play className="mr-2 inline h-4 w-4"/>Start service</button>:null}{!["IN SERVICE","COMPLETED","CANCELLED"].includes(appointment.status)?<button type="button" onClick={()=>setRescheduling(!rescheduling)} className="min-h-12 rounded-xl border border-[#173d32]/12 bg-white px-4 text-sm font-black">Reschedule</button>:null}<Link href={createHerWhatsappUrl(`Hi ${appointment.client.split(" ")[0]}, this is HER Salon & Wellness at Happy-Park regarding your ${appointment.service} appointment.`)} target="_blank" rel="noreferrer" className="inline-flex min-h-12 items-center rounded-xl border border-[#173d32]/12 bg-white px-4 text-sm font-black">Contact client</Link>{!["IN SERVICE","COMPLETED","CANCELLED"].includes(appointment.status)?<button type="button" onClick={()=>onStatus(appointment.id,"CANCELLED")} className="min-h-12 rounded-xl px-4 text-sm font-black text-rose-700">Cancel</button>:null}</div><p className="mt-5 text-xs text-[#7b8881]">All lifecycle and timer changes are demo-only and remain in memory. Completing a service does not represent payment collection.</p></DialogShell>; }

function ServiceTimerPanel({appointment,now,onPause,onResume,onComplete}:{appointment:HerAdminAppointment;now:number;onPause:()=>void;onResume:()=>void;onComplete:()=>void}) { const estimate=parseEstimatedDurationMs(appointment.duration); const remaining=getRemainingServiceMs(appointment,now); const overtime=getServiceOvertimeMs(appointment,now); const progress=getServiceProgress(appointment,now); const finish=getEstimatedFinishTime(appointment); const pausedFor=getCurrentPauseMs(appointment,now); return <section className={cn("mt-6 rounded-2xl border p-5 sm:p-6",appointment.pausedAt?"border-[#b28a4d]/35 bg-[#f5ead8]":overtime?"border-[#c98463]/30 bg-[#faeee7]":"border-[#173d32]/10 bg-white")}><div className="flex items-start justify-between gap-3"><div><p className="text-[10px] font-black uppercase tracking-[.18em] text-[#9a7139]">{appointment.pausedAt?"Service paused":overtime?"Estimated duration complete":"Service in progress"}</p><h3 className="mt-2 text-xl font-black">{appointment.service}</h3></div><StatusBadge status="IN SERVICE"/></div><div className="mt-6 grid grid-cols-2 gap-3 text-sm"><div><p className="text-xs text-[#7b8881]">Started</p><p className="mt-1 font-black">{formatLocalTime(appointment.serviceStartedAt)}</p></div><div><p className="text-xs text-[#7b8881]">Estimated finish</p><p className="mt-1 font-black">{estimate===null?"Not available":formatLocalTime(finish??undefined)}</p></div></div><div className="mt-7 text-center"><p className={cn("font-mono text-4xl font-black tracking-[-.04em] sm:text-5xl",overtime?"text-[#a45f43]":"text-[#173d32]")}>{estimate===null?"—":formatClockDuration(overtime||remaining||0)}</p><p className="mt-2 text-[10px] font-black uppercase tracking-[.18em] text-[#7b8881]">{estimate===null?"Estimated duration not set":overtime?"Over estimated time":appointment.pausedAt?`Paused for ${formatClockDuration(pausedFor)}`:"Remaining"}</p></div>{progress!==null?<div className="mt-6"><div role="progressbar" aria-label={`Service progress ${Math.round(progress)} percent`} aria-valuemin={0} aria-valuemax={100} aria-valuenow={Math.round(progress)} className="h-2.5 overflow-hidden rounded-full bg-[#173d32]/10"><div className={cn("h-full rounded-full transition-[width] duration-500",overtime?"bg-[#b87557]":"bg-[#173d32]")} style={{width:`${progress}%`}}/></div><p className="mt-2 text-xs text-[#75827b]">{Math.round(progress)}% of estimated service duration elapsed</p></div>:<p className="mt-6 rounded-xl bg-[#f5ead8] p-4 text-sm font-bold text-[#76572f]">Estimated duration not set. Live countdown and finish calculations are unavailable, but the service can still be completed.</p>}<div className="mt-7 grid grid-cols-2 gap-3"><button type="button" aria-label={appointment.pausedAt?"Resume service timer":"Pause service timer"} onClick={appointment.pausedAt?onResume:onPause} className="min-h-14 rounded-xl border border-[#173d32]/15 bg-white text-sm font-black">{appointment.pausedAt?<><Play className="mr-2 inline h-4 w-4"/>Resume</>:<><Pause className="mr-2 inline h-4 w-4"/>Pause</>}</button><button type="button" onClick={onComplete} className="min-h-14 rounded-xl bg-[#173d32] px-3 text-sm font-black text-white">Complete service</button></div></section>; }

function CompletionSummary({appointment}:{appointment:HerAdminAppointment}) { const estimate=parseEstimatedDurationMs(appointment.duration); const actual=getActiveServiceElapsedMs(appointment,appointment.serviceCompletedAt); const variance=getServiceVarianceMs(appointment); return <section className="mt-6 rounded-2xl border border-emerald-200 bg-emerald-50 p-5 sm:p-6"><div className="flex items-center gap-3 text-emerald-800"><span className="grid h-10 w-10 place-items-center rounded-full bg-emerald-100"><Check className="h-5 w-5"/></span><div><p className="text-[10px] font-black uppercase tracking-[.16em]">Service completed</p><h3 className="mt-1 text-xl font-black">{appointment.service}</h3></div></div><dl className="mt-6 grid grid-cols-2 gap-5 text-sm"><div><dt className="text-xs text-[#718078]">Estimated</dt><dd className="mt-1 font-black">{estimate===null?"Not set":appointment.duration}</dd></div><div><dt className="text-xs text-[#718078]">Actual active duration</dt><dd className="mt-1 font-black">{formatCompactDuration(actual)}</dd></div><div><dt className="text-xs text-[#718078]">Started</dt><dd className="mt-1 font-black">{formatLocalTime(appointment.serviceStartedAt)}</dd></div><div><dt className="text-xs text-[#718078]">Completed</dt><dd className="mt-1 font-black">{formatLocalTime(appointment.serviceCompletedAt)}</dd></div><div className="col-span-2"><dt className="text-xs text-[#718078]">Difference</dt><dd className="mt-1 font-black">{variance===null?"Variance unavailable":variance===0?"Matched estimate":`${formatCompactDuration(Math.abs(variance))} ${variance<0?"under":"over"} estimate`}</dd></div></dl></section>; }

function ClientDialog({client,appointments,onClose}:{client:HerAdminClient;appointments:HerAdminAppointment[];onClose:()=>void}){return <DialogShell title={client.name} onClose={onClose}><div className="mt-6 grid gap-4 sm:grid-cols-2"><Card><p className="text-[10px] font-black uppercase tracking-[.14em] text-[#9a7139]">Contact information</p><p className="mt-4 font-bold">{client.phone}</p><p className="mt-2 text-sm">{client.email}</p></Card><Card><p className="text-[10px] font-black uppercase tracking-[.14em] text-[#9a7139]">Service preferences</p><p className="mt-4 font-bold">{client.preferredService}</p><p className="mt-2 text-sm text-[#6d7d74]">{client.note}</p></Card></div><h3 className="mt-7 font-serif text-xl">Appointment history &amp; upcoming</h3><div className="mt-3 space-y-2">{appointments.map((item)=><div key={item.id} className="flex items-center justify-between rounded-xl bg-white p-4"><div><p className="font-bold">{item.service}</p><p className="text-xs text-[#748179]">{item.dayLabel} · {item.time}</p></div><StatusBadge status={item.status}/></div>)}</div><p className="mt-5 text-xs text-[#7b8881]">This directory contains salon contact and preference information only. It is not a health record.</p></DialogShell>}

function ConsultationDialog({item,onClose,onReviewed,onConvert}:{item:HerConsultationRequest;onClose:()=>void;onReviewed:()=>void;onConvert:()=>void}){return <DialogShell title={`${item.client} · Consultation`} onClose={onClose}><dl className="mt-6 divide-y divide-[#173d32]/8 rounded-2xl bg-white px-5">{[["General concern",item.concern],["Requested",item.requested],["Preferred contact",item.contactPreference],["Customer note",item.note??"No optional note provided"]].map(([term,value])=><div key={term} className="py-4"><dt className="text-[10px] font-black uppercase tracking-[.12em] text-[#8b9791]">{term}</dt><dd className="mt-1 font-bold">{value}</dd></div>)}</dl><div className="mt-6 flex flex-wrap gap-2"><button type="button" onClick={onReviewed} className="min-h-11 rounded-xl bg-[#173d32] px-4 text-sm font-black text-white">Mark reviewed</button><Link href={createHerWhatsappUrl()} target="_blank" rel="noreferrer" className="inline-flex min-h-11 items-center rounded-xl border bg-white px-4 text-sm font-black">Contact</Link><button type="button" onClick={onConvert} className="min-h-11 rounded-xl border bg-white px-4 text-sm font-black">Convert to appointment</button></div><p className="mt-5 text-xs text-[#7b8881]">No automated recommendation or diagnosis is made.</p></DialogShell>}

function ServiceDialog({service,onClose,onSave}:{service:HerAdminService;onClose:()=>void;onSave:(item:HerAdminService)=>void}) { const [draft,setDraft]=useState(service); return <DialogShell title="Edit demo service" onClose={onClose}><div className="mt-6 grid gap-4 sm:grid-cols-2"><AdminField label="Name" value={draft.name} onChange={(value)=>setDraft({...draft,name:value})}/><AdminField label="Price" value={draft.price} onChange={(value)=>setDraft({...draft,price:value})}/><AdminField label="Duration" value={draft.duration} onChange={(value)=>setDraft({...draft,duration:value})}/><label className="text-sm font-bold">Status<select value={draft.status} onChange={(e)=>setDraft({...draft,status:e.target.value as HerAdminService["status"]})} className="mt-2 min-h-12 w-full rounded-xl border bg-white px-3"><option>ACTIVE</option><option>HIDDEN</option></select></label><Toggle label="Online Booking" checked={draft.onlineBooking} onChange={(value)=>setDraft({...draft,onlineBooking:value})}/><Toggle label="Consultation Required" checked={draft.consultationRequired} onChange={(value)=>setDraft({...draft,consultationRequired:value})}/></div><p className="mt-5 rounded-xl bg-[#f1e5d2] p-4 text-xs font-black text-[#75572f]">DEMO CHANGE — NOT SAVED TO PRODUCTION</p><button type="button" onClick={()=>onSave(draft)} className="mt-5 min-h-11 w-full rounded-xl bg-[#173d32] text-sm font-black text-white">Apply demo change</button></DialogShell>; }

function NewAppointmentDialog({clients,services,onClose,onCreate}:{clients:HerAdminClient[];services:HerAdminService[];onClose:()=>void;onCreate:(item:HerAdminAppointment)=>void}) { const [clientId,setClientId]=useState(clients[0].id); const [newClientName,setNewClientName]=useState(""); const [serviceId,setServiceId]=useState(services[0].id); const [date,setDate]=useState("2026-10-01"); const [time,setTime]=useState("8:00 AM"); const [contact,setContact]=useState("WhatsApp"); const [note,setNote]=useState(""); function submit(e:React.FormEvent){e.preventDefault();const existing=clients.find((i)=>i.id===clientId);const clientName=clientId==="new"?newClientName:existing?.name??"Demo client";const service=services.find((i)=>i.id===serviceId)!;const price=Number(service.price.match(/[\d,]+/)?.[0].replaceAll(",","")??0);onCreate({id:`HER-DEMO-${Date.now().toString().slice(-4)}`,clientId:clientId==="new"?`demo-${Date.now()}`:clientId,client:clientName,date,dayLabel:"Upcoming",time,serviceId,service:service.name,duration:service.duration,price,status:"CONFIRMED",contactPreference:contact as HerAdminAppointment["contactPreference"],note});} return <DialogShell title="New demo appointment" onClose={onClose}><form onSubmit={submit} className="mt-6 grid gap-4 sm:grid-cols-2"><label className="text-sm font-bold">Client<select value={clientId} onChange={(e)=>setClientId(e.target.value)} className="mt-2 min-h-12 w-full rounded-xl border bg-white px-3">{clients.map((i)=><option key={i.id} value={i.id}>{i.name}</option>)}<option value="new">+ New client</option></select></label>{clientId==="new"?<AdminField label="New client name" value={newClientName} onChange={setNewClientName}/>:null}<label className="text-sm font-bold">Service<select value={serviceId} onChange={(e)=>setServiceId(e.target.value)} className="mt-2 min-h-12 w-full rounded-xl border bg-white px-3">{services.filter((i)=>i.status==="ACTIVE").map((i)=><option key={i.id} value={i.id}>{i.name} · {i.price}</option>)}</select></label><AdminField label="Date" type="date" value={date} onChange={setDate}/><AdminField label="Time" value={time} onChange={setTime}/><label className="text-sm font-bold">Contact preference<select value={contact} onChange={(e)=>setContact(e.target.value)} className="mt-2 min-h-12 w-full rounded-xl border bg-white px-3"><option>WhatsApp</option><option>Phone</option><option>Email</option></select></label><label className="text-sm font-bold sm:col-span-2">Optional note<textarea value={note} onChange={(e)=>setNote(e.target.value)} rows={3} className="mt-2 w-full rounded-xl border bg-white p-3"/></label><p className="text-xs text-[#7b8881] sm:col-span-2">Creates a session-only appointment. A new client name remains ephemeral and is not added to production records. No availability check, message, payment, or database write occurs.</p><button type="submit" disabled={clientId==="new"&&!newClientName.trim()} className="min-h-12 rounded-xl bg-[#173d32] text-sm font-black text-white disabled:opacity-35 sm:col-span-2">Create demo appointment</button></form></DialogShell>; }

function AdminField({label,value,onChange,type="text"}:{label:string;value:string;onChange:(value:string)=>void;type?:string}){return <label className="text-sm font-bold">{label}<input type={type} required value={value} onChange={(e)=>onChange(e.target.value)} className="mt-2 min-h-12 w-full rounded-xl border bg-white px-3"/></label>}
function Toggle({label,checked,onChange}:{label:string;checked:boolean;onChange:(value:boolean)=>void}){return <label className="flex min-h-12 items-center justify-between rounded-xl border bg-white px-4 text-sm font-bold">{label}<input type="checkbox" checked={checked} onChange={(e)=>onChange(e.target.checked)} className="h-5 w-5 accent-[#173d32]"/></label>}
